import json,sys
d=json.load(sys.stdin)
hs=d['hotspots']
byid={h['node_id']:h for h in hs}
def parname(h):
    p=byid.get(h['parent_id'])
    return (p['snippet'].replace(chr(10),' ; ')[:30] if p else 'None')
for h in hs:
    if 'cases' in h['snippet'][:12] or h['class']=='Kernel' or h['syntax_kind'] in ('Lean.Parser.Tactic.cases',):
        print(round(h['heartbeats'],1),'nid%d'%h['node_id'],'par:',parname(h),'|',h['snippet'].replace(chr(10),' ; ')[:50])
\" 2>&1 | head -40"

